# Lesson 2, part 1 (second half): index points, the multiplier, the rules, European and American, swaps, comparison, check.


def _B_ar(txt, d, c, n=0):
    """One labelled arrow of a flow diagram. d: 'r' points right, 'l' points left. c: colour class."""
    a = f'<div class="b-ar b-{d} {c}">{TX(txt)}</div>'
    return ST(n, a) if n else a


def _B_nd(name, sub='', me=False):
    s = f'<small>{TX(sub)}</small>' if sub else ''
    return f'<div class="b-nd{" b-me" if me else ""}"><b>{TX(name)}</b>{s}</div>'


# ---------------------------------------------------------------- index points
_t, _n = GT(['מה קורה', 'רמת המדד (נקודות)', 'השינוי (נקודות)', 'בשקלים, בחוזה אחד'], [
    ['<b>היום</b>', '4,000', ('0', 'נקודת המוצא'), ('200,000', 'החשיפה: $4,000 × 50$')],
    ['<b>עלייה של נקודה</b>', ('4,001', '$4,000 + 1$'), '$+1$', ('$+50$', '$1 × 50$')],
    ['<b>עלייה של 2%</b>', ('4,080', '$4,000 × 1.02$'), ('$+80$', '$4,080 − 4,000$'), ('$+4,000$', '$80 × 50$')],
    ['<b>ירידה של 5%</b>', ('3,800', '$4,000 × 0.95$'), ('$-200$', '$3,800 − 4,000$'), ('$-10,000$', '$-200 × 50$')]], 4)
S('s-pts', 'נקודות של מדד', 'נקודות של מדד: מה זה, ואיך הן הופכות לשקלים',
  '<div class="row top b-cols"><div class="col b-defs">'
  + DEF('מדד (Index)', 'מספר אחד שמסכם את מחירי הרבה מניות. כשרוב המניות עולות, גם המדד עולה.', 'מדד ת״א 35 מסכם את 35 המניות הגדולות בבורסה בתל אביב. המדד עלה מ-4,000 ל-4,040? הוא עלה ב-1%.', 1, cls='mini')
  + DEF('נקודה (Index point)', 'היחידה שבה המדד נמדד. זה מספר, ולא מחיר בשקלים: אי אפשר לקנות ״נקודה״ בחנות.', 'המדד עלה מ-4,000 ל-4,040: הוא עלה ב-40 נקודות. כמה שקלים זה? תלוי בחוזה.', 2, cls='mini')
  + DEF('מכפיל (Multiplier)', 'כמה שקלים שווה נקודה אחת במדד, בחוזה אחד. הבורסה קובעת אותו לכל חוזה. בחוזים על מדד ת״א 35, נקודה שווה 50 ש״ח.', 'מכפיל 50: נקודה אחת שווה 50 ש״ח, ו-40 נקודות שוות $40 × 50 = 2,000$ ש״ח.', 3, trm='mult', cls='mini')
  + '</div><div class="col b-ex">'
  + '<div class="card qstem"><p>' + TX('קרן השקעות קונה (Long) [[futures|חוזה עתידי (Futures)]] אחד על מדד מניות שעומד היום על 4,000 נקודות, במחיר חוזה (K) של 4,000 נקודות. המדד נמדד בנקודות, ובחוזה הזה כל נקודה במדד שווה 50 ש״ח: זה המכפיל. <b>נדרש:</b> מה החשיפה של הקרן בשקלים, ומה הרווח או ההפסד שלה אם המדד יעלה בנקודה אחת, יעלה ב-2%, או ירד ב-5%?') + '</p></div>'
  + _t + ST(_n, '<div class="card fmline"><b class="ct">הכלל</b> ' + TX('<b>[[expo|חשיפה (Exposure)]] בשקלים</b> = רמת המדד בנקודות × מכפיל. <b>רווח או הפסד בשקלים</b> = השינוי בנקודות × מכפיל. בקונה (Long) של החוזה: $(S_{T} − K) × 50$.') + '</div>')
  + '</div></div>', kick=f'חלק {CUR[0]} · הגדרה בהדרגה')

# ---------------------------------------------------------------- the multiplier, on an option
S('s-mult', 'המכפיל', 'המכפיל (Multiplier) באופציה: מנקודות לשקלים',
  '<div class="card qstem"><p>' + TX('משקיע מעריך שמדד ת״א 35 יעלה, ולכן הוא קונה אופציית רכש (Call) אחת על המדד. מחיר המימוש (K) הוא 4,300 נקודות, והפרמיה (c) ששילם היא 60 נקודות. המדד נמדד בנקודות, ובחוזה הזה כל נקודה במדד שווה 50 ש״ח: זה המכפיל (Multiplier). ביום הפקיעה המדד עומד על 4,400 נקודות. <b>נדרש:</b> מה הרווח שלו בנקודות, ומה הרווח שלו בשקלים?') + '</p></div>'
  + '<div class="row top b-cols"><div class="col b-main">'
  + TABLES(['מה מחשבים', 'הערך', 'איך ולמה'], [
      ['<b>המדד בפקיעה</b> ($S_{T}$)', '4,400 נקודות', 'נתון: רמת המדד ביום הפקיעה'],
      ['<b>מחיר המימוש</b> ($K$)', '4,300 נקודות', 'נתון בחוזה'],
      ['<b>[[payoff|התזרים בפקיעה (Payoff)]]</b>', '100 נקודות', '$max(S_{T} − K, 0) = max(4,400 − 4,300, 0)$'],
      ['<b>[[premium|הפרמיה]]</b> ($c$)', '60 נקודות', 'נתון: שולמה היום, וגם היא בנקודות'],
      ['<b>[[pnl|הרווח בנקודות (P&L)]]</b>', '40 נקודות', 'תזרים פחות פרמיה: $100 − 60$'],
      ['<b>המכפיל</b> (Multiplier)', '50 ש״ח לנקודה', 'נתון: כמה שקלים שווה נקודה אחת'],
      ['<b>הרווח בשקלים</b>', '2,000 ש״ח', 'רווח בנקודות × מכפיל: $40 × 50$']], 'mtab') + '</div><div class="col b-side">'
  + ST(8, '<div class="card"><b class="ct">אותה תוצאה, בדרך שנייה: קודם הכול לשקלים</b>' + TABLE(['מה מחשבים', 'הערך', 'איך'], [
      ['התזרים בשקלים', '5,000 ש״ח', '$100 × 50$'],
      ['הפרמיה בשקלים', '3,000 ש״ח', '$60 × 50$'],
      ['<b>הרווח בשקלים</b>', '2,000 ש״ח', '$5,000 − 3,000$']], 'mtab') + '</div>')
  + BAND('trap', 'לחסר 60 ש״ח מ-5,000 ש״ח. הפרמיה נתונה בנקודות, ולכן גם אותה כופלים במכפיל: $60 × 50 = 3,000$ ש״ח.', 9)
  + BAND('note', 'בשני חוזים כופלים גם במספר החוזים: $40 × 50 × 2 = 4,000$ ש״ח. זה התרגיל הבא, באקסל.', 10)
  + '</div></div>', kick=f'חלק {CUR[0]} · בנייה בהדרגה')

_d = {'A1': 'מחיר מימוש (K)', 'B1': 4300, 'A2': 'פרמיה (נקודות)', 'B2': 60, 'A3': 'מכפיל (ש״ח)', 'B3': 50, 'A4': 'מספר חוזים', 'B4': 2, 'A6': 'מדד בפקיעה', 'B6': 'תזרים (נקודות)', 'C6': 'רווח (נקודות)', 'D6': 'רווח (ש״ח)'}
_s = {}
for i, p in enumerate([4200, 4300, 4360, 4400, 4500]):
    r = 7 + i; _d[f'A{r}'] = p; _s[f'B{r}'] = f'=MAX(A{r}-$B$1,0)'; _s[f'C{r}'] = f'=B{r}-$B$2'; _s[f'D{r}'] = f'=C{r}*$B$3*$B$4'
XLS('x-mult', 'אקסל: המכפיל', 'אקסל: מנקודות לשקלים',
    'משקיע מעריך שמדד מניות, שעומד היום על 4,250 נקודות, יעלה עד מועד הפקיעה. לכן הוא רכש <b>שתי אופציות רכש (Call)</b> על המדד. מחיר המימוש (K) הוא 4,300 נקודות, הפרמיה (c) ששילם היא 60 נקודות לאופציה. המדד נמדד בנקודות, ובחוזה הזה כל נקודה במדד שווה 50 ש״ח: זה המכפיל (Multiplier). <b>נדרש:</b> הציגו בטבלה את התזרים בנקודות, את הרווח בנקודות ואת הרווח בשקלים של שתי האופציות יחד, כשהמדד בפקיעה נע בין 4,200 ל-4,500 נקודות. באיזה מדד הרווח בדיוק אפס?',
    _d, _s, [170, 140, 130, 120], [6], hints=['תזרים: MAX של המדד פחות K, ואפס.', 'רווח בנקודות: תזרים פחות פרמיה.', 'רווח בשקלים: רווח בנקודות × מכפיל × מספר חוזים.'], remind='<b>תזרים בנקודות</b> = $max(S_{T} − K, 0)$. באקסל: MAX של המדד פחות מחיר המימוש, ואפס.<br><b>רווח בנקודות</b> = תזרים − פרמיה.<br><b>רווח בשקלים</b> = רווח בנקודות × מכפיל (ש״ח לכל נקודה) × מספר האופציות.', partial=['B7', 'C7', 'D7'],
    chart=CH(['A7', 'A11'], [dict(y=['D7', 'D11'], c=PNLC, lab='רווח')], 4200, 4500, -10000, 20000, [4200, 4300, 4400, 4500], [-10000, 0, 10000, 20000], xl='מדד בפקיעה', yl='רווח (ש״ח)'),
    done='במדד 4,360 הרווח אפס: $K + c = 4,300 + 60$. זו נקודת האיזון (Break-even). מעליה כל נקודה מוסיפה $50 × 2 = 100$ ש״ח.')

# ---------------------------------------------------------------- the rules
S('s-rules', 'עכשיו הכלל', 'עכשיו, אחרי כל הדוגמאות: הכללים',
  ST(1, '<b class="ct">הסימנים</b><span>' + TX('$S_{T}$: מחיר נכס הבסיס בפקיעה') + '</span><span>' + TX('$K$: מחיר המימוש (Strike)') + '</span><span>' + TX('$c$: הפרמיה של Call') + '</span><span>' + TX('$p$: הפרמיה של Put') + '</span>', cls='card b-leg')
  + TABLES(['פוזיציה', 'תזרים בפקיעה<br>(Payoff)', 'רווח<br>(P&L)', 'נקודת איזון<br>(Break-even)', 'רווח<br>מרבי', 'הפסד<br>מרבי'], [
      ['קונה רכש (Long Call)', '$max(S_{T} − K, 0)$', '$Payoff − c$', '$K + c$', 'ללא תקרה', '$c$'],
      ['כותב רכש (Short Call)', '$−max(S_{T} − K, 0)$', '$Payoff + c$', '$K + c$', '$c$', 'ללא תקרה'],
      ['קונה מכר (Long Put)', '$max(K − S_{T}, 0)$', '$Payoff − p$', '$K − p$', '$K − p$', '$p$'],
      ['כותב מכר (Short Put)', '$−max(K − S_{T}, 0)$', '$Payoff + p$', '$K − p$', '$p$', '$K − p$'],
      ['קונה אקדמה (Long Forward)', '$S_{T} − K$', 'Payoff: אין פרמיה', '$K$', 'ללא תקרה', '$K$'],
      ['מוכר אקדמה (Short Forward)', '$K − S_{T}$', 'Payoff: אין פרמיה', '$K$', '$K$', 'ללא תקרה']], 'b-rt', 2)
  + '<div class="row eq2 b-bands">'
  + BAND('dg', 'כל זוג הוא תמונת ראי. הקונה והכותב חולקים את אותה נקודת איזון, ומה שאחד מרוויח, השני מפסיד.', 8)
  + BAND('note', 'הטבלה היא לנכס אחד. בחוזה על מדד כופלים במכפיל ובמספר החוזים: 40 נקודות, מכפיל 50, שני חוזים: $40 × 50 × 2 = 4,000$ ש״ח.', 9)
  + '</div>', kick=f'חלק {CUR[0]} · מהפרט אל הכלל')

# ---------------------------------------------------------------- European and American
_ok, _no = '<b class="b-ok">מותר</b>', '<b class="b-no">אסור</b>'
S('s-euro', 'אירופאית ואמריקאית: הגדרה', 'מתי מותר לממש: אירופאית (European) ואמריקאית (American)',
  '<div class="card qstem"><p>' + TX('דנית מחזיקה אופציית רכש (Call) על מניה, במחיר מימוש (K) של 100 ש״ח. נשארו חודשיים עד מועד הפקיעה (T). המניה נסחרת היום ($S$) ב-120 ש״ח, והאופציה עצמה נסחרת בשוק ב-23 ש״ח: זו הפרמיה ($c$) שקונה אחר מוכן לשלם עליה היום. <b>נדרש:</b> מה מותר לדנית לעשות היום אם האופציה אירופאית, ומה אם היא אמריקאית? ומה הכי משתלם לה?') + '</p></div>'
  + '<div class="row eq2 top b-r1">'
  + DEF('אופציה אירופאית (European option)', 'אפשר לממש רק במועד הפקיעה.', 'אופציה לחודשיים: מממשים רק ביום הפקיעה, בעוד חודשיים. כך, למשל, האופציות על מדד ת״א 35 בבורסה בתל אביב.', 1, trm='european', cls='mini')
  + DEF('אופציה אמריקאית (American option)', 'אפשר לממש בכל יום עד מועד הפקיעה, כולל בו.', 'אופציה לחודשיים: אפשר לממש היום, בעוד שבוע או ביום הפקיעה. כך, לרוב, אופציות רגילות על מניות בארה״ב.', 2, trm='american', cls='mini')
  + '</div><div class="row top b-r2"><div class="col b-allow"><b class="ct">מה מותר לדנית לעשות היום?</b>'
  + TABLES(['הפעולה, היום', 'אירופאית', 'אמריקאית', 'מה זה נותן לה'], [
      ['לממש: לקנות ב-100 מניה ששווה 120', _no, _ok, '20 ש״ח'],
      ['למכור את האופציה בשוק', _ok, _ok, '23 ש״ח'],
      ['להמתין לפקיעה', _ok, _ok, '$max(S_{T} − 100, 0)$']], 'mtab b-tt', 3)
  + '</div><div class="col b-tv"><b class="ct">ערך הזמן: למה למכור ולא לממש?</b>'
  + TABLES(['מה מחשבים', 'הערך', 'איך ולמה'], [
      ['מימוש היום', '20 ש״ח', '$S − K = 120 − 100$'],
      ['מכירה בשוק ($c$)', '23 ש״ח', 'נתון: המחיר בשוק'],
      ['<b>[[timev|ערך זמן (Time value)]]</b>', '3 ש״ח', '$c − (S − K) = 23 − 20$']], 'mtab b-tt', 6)
  + '</div></div>'
  + BAND('dg', 'גם באמריקאית, דנית תעדיף למכור ב-23 ולא לממש ב-20, כי מימוש מוקדם מוותר על ערך הזמן. זכות נוספת לא מורידה שווי: אמריקאית שווה לפחות כמו אירופאית זהה. מתי מימוש מוקדם כדאי? בשיעור 8.', 9)
  , kick=f'חלק {CUR[0]} · הגדרה והדגמה')

# ---------------------------------------------------------------- swaps: definitions
S('s-swap', 'עסקת החלפה: הגדרה', 'אבן הבניין האחרונה: עסקת החלפה (Swap)',
  '<div class="two4 b-g4">'
  + DEF('עסקת החלפה (Swap)', 'הסכם שבו שני צדדים מחליפים ביניהם תשלומים בכמה מועדים עתידיים, לפי נוסחה שנקבעה מראש.', 'בכל סוף שנה, במשך 3 שנים, חברה משלמת לבנק 100,000 ש״ח, והבנק משלם לה לפי מחיר הנפט באותה שנה. שנה שבה הבנק חייב 130,000: עובר רק ההפרש, 30,000 ש״ח, מהבנק לחברה.', 1, trm='swap', cls='mini')
  + DEF('ריבית קבועה (Fixed rate) וריבית משתנה (Floating rate)', 'ריבית קבועה נקבעת היום לכל התקופה. ריבית משתנה מתעדכנת בכל שנה לפי ריבית השוק, ולכן לא ידועה מראש.', 'הלוואה של 1,000,000 ש״ח: בריבית קבועה של 4.5% משלמים 45,000 ש״ח בכל שנה. בריבית משתנה: 35,000 בשנה שבה ריבית השוק 3.5%, ו-60,000 בשנה שבה היא 6%.', 2, cls='mini')
  + DEF('ערך נקוב (Notional amount)', 'הסכום שעליו מחשבים את הריבית בעסקה. הוא עצמו לא עובר בין הצדדים.', 'על ערך נקוב של 10,000,000 ש״ח, ריבית של 1% היא 100,000 ש״ח בשנה. 10,000,000 עצמם לא משולמים.', 3, trm='notional', cls='mini')
  + DEF('עסקת החלפת ריביות (Interest Rate Swap, IRS)', 'עסקת החלפה שבה צד אחד משלם ריבית קבועה, והצד השני משלם ריבית משתנה, על אותו ערך נקוב ובאותם מועדים.', 'ערך נקוב 1,000,000 ש״ח: החברה משלמת לבנק 5% קבוע, 50,000 ש״ח בשנה. בשנה שבה ריבית השוק 6%, הבנק חייב לה 60,000. עובר רק ההפרש: 10,000 ש״ח מהבנק לחברה.', 4, cls='mini')
  + '</div>'
  + ST(5, '<b class="ct">ה-IRS מהדוגמה, בתרשים: מי משלם למי בכל שנה</b><div class="b-fl">' + _B_nd('החברה', 'משלמת קבוע', True)
       + '<div class="b-lk">' + _B_ar('ריבית קבועה: $5% × 1,000,000 = 50,000$ ש״ח', 'l', 'b-fx')
       + _B_ar('ריבית משתנה: ריבית השוק × 1,000,000. בשנה של 6%, 60,000 ש״ח', 'r', 'b-fv') + '</div>'
       + _B_nd('הבנק', 'משלם משתנה') + '</div>'
       + '<p class="b-cap">' + TX('<b>בפועל עובר רק ההפרש:</b> בשנה של 6%, 10,000 ש״ח מהבנק לחברה. הערך הנקוב לא עובר.') + '</p>', cls='card b-diag'),
  kick=f'חלק {CUR[0]} · הגדרה והדגמה')

# ---------------------------------------------------------------- swaps: the story
S('s-swap2', 'IRS: הסיפור', 'עסקת החלפת ריביות (IRS): הסיפור, צעד אחר צעד',
  '<div class="row eq2 top"><div class="rl b-rl">'
  + RL(['<b>ההלוואה.</b> חברת נדל״ן לקחה מבנק א הלוואה של 10,000,000 ש״ח לשנתיים, בריבית משתנה. בכל שנה היא משלמת לבנק א את ריבית השוק של אותה שנה.',
        '<b>הבעיה.</b> שכר הדירה שהחברה גובה מהשוכרים קבוע. אם ריבית השוק תעלה מ-3.5% ל-6%, תשלום הריבית יעלה מ-350,000 ל-600,000 ש״ח בשנה, וההכנסות לא יזוזו.',
        '<b>מה החברה רוצה?</b> לדעת כבר היום כמה ריבית תשלם בכל שנה, כאילו לקחה הלוואה בריבית קבועה.',
        '<b>העסקה.</b> החברה חותמת עם בנק ב על עסקת החלפת ריביות (IRS), על ערך נקוב של 10,000,000 ש״ח, לשנתיים. בכל שנה: <b>החברה משלמת לבנק ב ריבית קבועה של 4.5%</b>, ו<b>בנק ב משלם לחברה את ריבית השוק</b> של אותה שנה.',
        '<b>ההלוואה לא משתנה.</b> החברה ממשיכה לשלם לבנק א ריבית משתנה. ה-IRS הוא חוזה נפרד, מול בנק אחר.',
        '<b>הרעיון.</b> את הריבית המשתנה שהחברה משלמת לבנק א, היא מקבלת חזרה מבנק ב. מה שנשאר לה לשלם הוא רק הריבית הקבועה, 4.5%.']) + '</div><div class="col b-side">'
  + '<div class="card b-diag"><b class="ct">מי משלם למי, בכל שנה</b><div class="b-fl b-fl3">'
  + _B_nd('בנק א', 'המלווה')
  + '<div class="b-lk">' + _B_ar('ריבית השוק', 'r', 'b-fv', 1) + '</div>'
  + _B_nd('החברה', '', True)
  + '<div class="b-lk">' + _B_ar('4.5% קבוע', 'l', 'b-fx', 4) + _B_ar('ריבית השוק', 'r', 'b-fv', 4) + '</div>'
  + _B_nd('בנק ב', 'הצד ב-IRS') + '</div>'
  + ST(6, '<p class="b-cap">' + TX('<b>ריבית השוק נכנסת מבנק ב ויוצאת לבנק א: היא מתקזזת.</b> העלות נטו = ריבית השוק + 4.5% − ריבית השוק = 4.5%.') + '</p>') + '</div>'
  + '<div class="row b-low">' + ST(7, '<b class="ct">כמה ריבית משלמת החברה, נטו?</b>' + TABLE(['', 'ריבית השוק 3.5%', 'ריבית השוק 6%'], [
      ['<b>בלי IRS</b>', '3.5%', '6%'],
      ['<b>עם IRS</b>', '4.5%', '4.5%']], 'mtab b-wo'), cls='card b-wo-c')
  + MEME('cool', 'החברה אחרי ה-IRS', 'ריבית השוק קופצת? אני משלמת 4.5%', 8) + '</div></div></div>', kick=f'חלק {CUR[0]} · בנייה בהדרגה')

# ---------------------------------------------------------------- swaps: the numbers
_t, _n = GT(['מה מחשבים', 'שנה 1: ריבית השוק 3.5%', 'שנה 2: ריבית השוק 6%'], [
    [('החברה משלמת לבנק א', 'ערך נקוב × ריבית השוק'), ('350,000', '$10,000,000 × 3.5%$'), ('600,000', '$10,000,000 × 6%$')],
    [('החברה משלמת לבנק ב', 'ערך נקוב × 4.5%'), ('450,000', '$10,000,000 × 4.5%$'), ('450,000', '$10,000,000 × 4.5%$')],
    [('בנק ב משלם לחברה', 'ערך נקוב × ריבית השוק'), ('350,000', '$10,000,000 × 3.5%$'), ('600,000', '$10,000,000 × 6%$')],
    [('העלות נטו של החברה', 'לבנק א + לבנק ב − מבנק ב'), ('450,000, כלומר 4.5%', '$350,000 + 450,000 − 350,000$'), ('450,000, כלומר 4.5%', '$600,000 + 450,000 − 600,000$')],
    [('מה עובר בפועל ב-IRS', 'רק ההפרש בין שני הצדדים'), ('החברה משלמת 100,000', '$450,000 − 350,000$'), ('בנק ב משלם 150,000', '$600,000 − 450,000$')]], cls='b-st')
S('s-swap3', 'IRS: החשבון', 'עסקת החלפת ריביות (IRS): החשבון, שנה אחר שנה',
  '<div class="row top b-cols"><div class="col b-q">'
  + '<div class="card qstem"><p>' + TX('חברת נדל״ן לקחה מבנק א הלוואה של 10,000,000 ש״ח לשנתיים, בריבית משתנה: ריבית השוק של כל שנה. מול בנק ב היא חתמה על עסקת החלפת ריביות (IRS) על אותו ערך נקוב: היא משלמת לבנק ב 4.5% קבוע, ובנק ב משלם לה את ריבית השוק. בשנה 1 ריבית השוק 3.5%, ובשנה 2 היא 6%.') + '</p><p>' + TX('<b>נדרש:</b> כמה ריבית משלמת החברה בכל שנה, נטו? הסכומים להמחשה, בלי מרווח של הבנק.') + '</p></div>'
  + TOON('seesaw', 'ריבית השוק עולה או יורדת, והחברה נשארת באמצע: 4.5%.', _n + 1)
  + '</div><div class="col b-main">' + _t
  + BAND('dg', 'בשתי השנים העלות נטו היא 450,000 ש״ח, כלומר 4.5%. העלייה בריבית השוק לא נגעה בחברה. המחיר: אם הריבית הייתה יורדת ל-2%, היא עדיין הייתה משלמת 4.5%.', _n)
  + '</div></div>', kick=f'חלק {CUR[0]} · בנייה בהדרגה')

